#include <bits/stdc++.h>
#include <atcoder/all>

using namespace std;
using namespace atcoder;

#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void) {
	int n;
	cin>>n;
	vector<int>a(n),b(n);
	fenwick_tree<long long> c(n),d(n);
	long long z=0;
	rep(i,n){
		cin>>a[i];
		z+=c.sum(a[i],n);
		c.add(a[i]-1,1);
	}
	rep(i,n){
		cin>>b[i];
		z+=d.sum(b[i],n);
		d.add(b[i]-1,1);
	}
	sort(a.begin(),a.end());
	sort(b.begin(),b.end());
	rep(i,n)if(a[i]!=b[i]){
		cout<<"No"<<endl;
		return 0;
		}
	rep(i,n-1)if(a[i]==a[i+1]){
		cout<<"Yes"<<endl;
		return 0;
		}
	if(z%2)cout<<"No"<<endl;
	else cout<<"Yes"<<endl;
	return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    using namespace std;

    unsigned N;
    cin >> N;
    vector<unsigned> A(N), B(N);
    for (auto &&a : A)
        cin >> a;
    for (auto &&b : B)
        cin >> b;

    // count_A[i] = (i が A に出現した回数)
    // count_B[i] = (i が B に出現した回数)
    vector<unsigned> count_A(N), count_B(N);
    for (auto &&a : A)
        ++count_A[--a];
    for (auto &&b : B)
        ++count_B[--b];

    // 多重集合として一致していないなら No
    if (count_A != count_B) {
        cout << "No" << endl;
        return 0;
    }
    // そうでなく、同じ要素が複数回出現していたら Yes
    if (*max_element(begin(count_A), end(count_A)) >= 2) {
        cout << "Yes" << endl;
        return 0;
    }

    // P[i] = B[A[i]] が偶置換 <=> A[i] と B[i] の置換の偶奇は等しい
    vector<unsigned> P(N), inv_P(N);
    transform(begin(A), end(A), begin(P), [&B](auto i) { return B[i]; });
    for (unsigned i{}; i < N; ++i)
        inv_P[P[i]] = i;

    bool ans{true};
    for (unsigned i{}; i < N; ++i)
        if (i != P[i]) {
            // P[i] と i を swap
            swap(inv_P[i], inv_P[P[i]]);
            swap(P[i], P[inv_P[P[i]]]);
            ans ^= true;
        }
    cout << (ans ? "Yes" : "No") << endl;

    return 0;
}
